package com.skillbridge.api;
import jakarta.annotation.PostConstruct;import jakarta.persistence.*;import org.springframework.web.bind.annotation.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.*;import com.fasterxml.jackson.annotation.JsonAutoDetect;import java.time.*;import java.util.*;
record Envelope<T>(boolean success,T data,String message){static <T> Envelope<T> ok(T d){return new Envelope<>(true,d,"ok");}}
@Entity @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class User {@Id @GeneratedValue Long id;String name,email,university,bio,profilePicUrl,role;double rating;int completedProjects;boolean verified; User(){} User(String n,String e,String r){name=n;email=e;role=r;verified=true;university=r.equals("STUDENT")?"Stanford University":"";bio=r.equals("STUDENT")?"Product-minded student creator building thoughtful digital experiences.":"Verified SkillBridge client.";rating=4.9;completedProjects=r.equals("STUDENT")?18:0;}}
@Entity @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Job {@Id @GeneratedValue Long id;String title,company,location,tags;double payRate,distance;boolean remote,verified;LocalDateTime postedAt=LocalDateTime.now();Long clientId;Job(){}Job(String t,String c,double p,double d,String tag,boolean r){title=t;company=c;payRate=p;distance=d;tags=tag;remote=r;verified=true;location="Stanford, CA";}}
@Entity @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Application {@Id @GeneratedValue Long id;Long jobId,studentId;String introText,proposedRate,status;LocalDateTime submittedAt=LocalDateTime.now();}
@Entity @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Portfolio {@Id @GeneratedValue Long id;Long studentId;String title,category,year,thumbnailUrl;}
@Entity @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Review {@Id @GeneratedValue Long id;Long reviewerId,revieweeId,jobId;int rating;String comment;LocalDateTime createdAt=LocalDateTime.now();}
interface JobRepo extends JpaRepository<Job,Long>{} interface UserRepo extends JpaRepository<User,Long>{} interface ApplicationRepo extends JpaRepository<Application,Long>{List<Application> findByStudentId(Long id);} interface PortfolioRepo extends JpaRepository<Portfolio,Long>{List<Portfolio> findByStudentId(Long id);} interface ReviewRepo extends JpaRepository<Review,Long>{List<Review> findByRevieweeId(Long id);}
@RestController @RequestMapping("/api") class ApiController {final JobRepo jobs;final UserRepo users;final ApplicationRepo apps;final PortfolioRepo portfolios;final ReviewRepo reviews;ApiController(JobRepo j,UserRepo u,ApplicationRepo a,PortfolioRepo p,ReviewRepo r){jobs=j;users=u;apps=a;portfolios=p;reviews=r;} @GetMapping("/jobs") Envelope<?> list(@RequestParam(required=false)String category,@RequestParam(required=false)Double maxDistance,@RequestParam(required=false)Double minPay,@RequestParam(required=false)Double maxPay,@RequestParam(required=false)Boolean isRemote){return Envelope.ok(jobs.findAll().stream().filter(x->category==null||x.tags.contains(category)).filter(x->maxDistance==null||x.distance<=maxDistance).filter(x->minPay==null||x.payRate>=minPay).filter(x->maxPay==null||x.payRate<=maxPay).filter(x->isRemote==null||x.remote==isRemote).toList());}@GetMapping("/jobs/{id}") Envelope<?> job(@PathVariable Long id){return Envelope.ok(jobs.findById(id).orElseThrow());}@GetMapping("/jobs/nearby") Envelope<?> nearby(@RequestParam double lat,@RequestParam double lng,@RequestParam double radius){return Envelope.ok(jobs.findAll().stream().filter(j->j.distance<=radius).toList());}@GetMapping("/users/{id}") Envelope<?> user(@PathVariable Long id){return Envelope.ok(users.findById(id).orElseThrow());}@GetMapping("/users/{id}/portfolio") Envelope<?> portfolio(@PathVariable Long id){return Envelope.ok(portfolios.findByStudentId(id));}@GetMapping("/users/{id}/reviews") Envelope<?> review(@PathVariable Long id){return Envelope.ok(reviews.findByRevieweeId(id));}@PostMapping("/users/register") Envelope<?> register(@RequestBody User u){return Envelope.ok(users.save(u));}@PostMapping("/applications") Envelope<?> apply(@RequestBody Application a){a.status="PENDING";return Envelope.ok(apps.save(a));}@GetMapping("/applications") Envelope<?> applications(@RequestParam Long studentId){return Envelope.ok(apps.findByStudentId(studentId));}@PostMapping("/auth/login") Envelope<?> login(){return Envelope.ok(Map.of("token","mock-skillbridge-jwt"));}}
@Component class DataLoader {final JobRepo jobs;final UserRepo users;DataLoader(JobRepo j,UserRepo u){jobs=j;users=u;}@PostConstruct void load(){users.saveAll(List.of(new User("Aisha Raman","aisha@stanford.edu","STUDENT"),new User("Noah Lee","noah@stanford.edu","STUDENT"),new User("Maya Chen","maya@terralabs.com","CLIENT")));String[] t={"Brand identity for climate startup","Android app polish sprint","Social content launch","Technical writer","React landing page","Python tutor","Campus event photographer","Data dashboard","UX research assistant","SEO content editor"};String[] c={"Terra Labs","CampusLoop","Bloom Coffee","PixelWorks","Northstar","Learnly","Lens House","Civic Data","Dwell","Readwise"};for(int i=0;i<10;i++)jobs.save(new Job(t[i],c[i],20+i*3,.5+i*.4,i%3==0?"Design":i%3==1?"Coding":"Writing",i%2==0));}}
